package com.gymmind.ai.application;
import com.gymmind.ai.domain.*; import com.gymmind.knowledge.application.KnowledgeSearchService; import com.gymmind.iam.domain.model.RoleCode; import com.gymmind.shared.security.CurrentActor; import org.junit.jupiter.api.Test; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
class AiChatServiceTest { @Test void answerContainsTenantScopedSources(){var search=mock(KnowledgeSearchService.class);var model=mock(ChatModelGateway.class);when(search.search(any(),eq("q"))).thenReturn(List.of(new ContextSegment("c1","d1","source text")));when(model.complete(any(),any())).thenReturn("answer");var s=new DefaultAiChatService(search,model);var r=s.chat(actor(7L),"s1","q");assertThat(r.answer()).isEqualTo("answer");assertThat(r.sources()).containsExactly("c1");assertThat(r.citations()).containsExactly(new SourceCitation("c1","d1","source text"));verify(search).search(any(),eq("q"));} @Test void profileMemoryIsAddedOnlyToModelPrompt(){var search=mock(KnowledgeSearchService.class);var model=mock(ChatModelGateway.class);var memory=mock(AiMemoryService.class);when(search.search(any(),eq("q"))).thenReturn(List.of(new ContextSegment("c1","d1","source text")));when(memory.context(any())).thenReturn(List.of(new AiMemoryEntry(AiMemoryType.GOAL,"target","减重")));when(model.complete(any(),any())).thenReturn("answer");var s=new DefaultAiChatService(search,model,memory);s.chat(actor(7L),"s1","q");var prompt=org.mockito.ArgumentCaptor.forClass(String.class);verify(model).complete(prompt.capture(),any());assertThat(prompt.getValue()).contains("target=减重");verify(search).search(any(),eq("q"));} @Test void emptyContextReturnsEvidenceWarningWithoutCallingModel(){var search=mock(KnowledgeSearchService.class);var model=mock(ChatModelGateway.class);when(search.search(any(),eq("q"))).thenReturn(List.of());var s=new DefaultAiChatService(search,model);var r=s.chat(actor(7L),"s1","q");assertThat(r.answer()).contains("没有找到足够可靠的知识依据");assertThat(r.sources()).isEmpty();verifyNoInteractions(model);} @Test void nullModelAnswerReturnsReadableFallback(){var search=mock(KnowledgeSearchService.class);var model=mock(ChatModelGateway.class);when(search.search(any(),eq("q"))).thenReturn(List.of(new ContextSegment("c1","d1","source text")));when(model.complete(any(),any())).thenReturn(null);var s=new DefaultAiChatService(search,model);assertThat(s.chat(actor(7L),"s1","q").answer()).contains("模型暂时不可用");} @Test void platformCannotChat(){var s=new DefaultAiChatService(mock(KnowledgeSearchService.class),mock(ChatModelGateway.class));assertThatThrownBy(()->s.chat(platform(),"s","q")).isInstanceOf(com.gymmind.shared.error.BusinessException.class);} private CurrentActor actor(long t){return new CurrentActor(1L,t,Set.of(RoleCode.MEMBER),Set.of("ai:chat"),0,"t");} private CurrentActor platform(){return new CurrentActor(1L,null,Set.of(RoleCode.PLATFORM_ADMIN),Set.of(),0,"t");} }
